<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= html_escape($title); ?></title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/core@1.4.0/dist/css/tabler.min.css"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/icons-webfont@3.34.1/dist/tabler-icons.min.css"><link href="https://fonts.googleapis.com/css2?family=Nunito:wght@500;700;800;900&display=swap" rel="stylesheet"><style>body{font-family:Nunito,sans-serif;background:#0e1831;color:#fff;min-height:100vh}.shell{max-width:1050px;margin:auto;padding:26px 18px}.back{color:#dfe7ff;text-decoration:none}.hero{margin:18px 0 28px;padding:28px;background:linear-gradient(135deg,#49358f,#167495);border-radius:24px;box-shadow:0 14px 40px #0005}.hero h1{font-size:40px;margin:5px 0}.season-label{color:#f9dc83;font-weight:900;letter-spacing:.08em}.inventory{display:flex;gap:9px;overflow:auto;padding:4px 0 14px}.item{min-width:145px;background:#ffffff12;border:1px solid #ffffff26;border-radius:12px;padding:9px}.item span{font-size:25px}.world-map{position:relative;display:grid;gap:22px;padding:20px 0 70px}.world-map:before{content:'';position:absolute;left:50%;top:0;bottom:0;width:6px;background:repeating-linear-gradient(#e8c76c 0 15px,transparent 15px 25px);opacity:.45}.chapter{position:relative;width:46%;background:#fff;color:#18223b;padding:18px;border-radius:17px;text-decoration:none;box-shadow:0 10px 25px #0005;transition:.2s}.chapter:nth-child(even){margin-left:54%}.chapter:hover{transform:translateY(-4px)}.chapter:after{content:'';position:absolute;top:50%;right:-10%;width:10%;height:3px;background:#e8c76c}.chapter:nth-child(even):after{right:auto;left:-10%}.chapter.locked{filter:grayscale(1);opacity:.62;pointer-events:none}.chapter .icon{font-size:34px}.tag{font-size:11px;color:#7155bd;font-weight:900}.bar{height:7px;background:#e8e2f3;border-radius:8px;overflow:hidden}.bar i{display:block;height:100%;background:#6750b7}.lock{float:right;background:#202a43;color:#fff;border-radius:50%;padding:7px}@media(max-width:650px){.world-map:before{left:18px}.chapter,.chapter:nth-child(even){width:calc(100% - 36px);margin-left:36px}.chapter:after,.chapter:nth-child(even):after{left:-18px;right:auto;width:18px}.hero h1{font-size:32px}}</style></head><body><main class="shell"><a class="back" href="<?= base_url('belajar/english-quest'); ?>"><i class="ti ti-arrow-left"></i> Pilih Season</a><section class="hero"><small>WORLD MAP · ENGLISH QUEST</small><div class="season-label">SEASON <?= (int)($season['sort_order']??1); ?> · <?= html_escape($season['title']??'The First Quest'); ?></div><h1>Pilih jalan petualanganmu</h1><p><?= html_escape($season['description']??'Selesaikan satu chapter untuk membuka wilayah berikutnya.'); ?></p><div class="inventory"><?php if($inventory): foreach($inventory as $item): ?><div class="item"><span><?= html_escape($item['item_icon']); ?></span><b><?= html_escape($item['item_name']); ?></b><small class="d-block">Jumlah <?= (int)$item['quantity']; ?></small></div><?php endforeach; else: ?><div class="item"><span>🎒</span><b>Tas masih kosong</b><small class="d-block">Mulai quest untuk mendapat item.</small></div><?php endif; ?></div></section><?php if($this->session->flashdata('error')): ?><div class="alert alert-warning"><?= html_escape($this->session->flashdata('error')); ?></div><?php endif; ?><section class="world-map"><?php $icons=['📚','🛒','🌲','🪐','🎭','🐬','🏰','⛰️','🐲','🏴‍☠️','🗿','🦾','☁️','🛕','❄️'];foreach($episodes as $i=>$e):$total=max(1,(int)$e['scene_count']);$current=(int)($e['current_scene']??0);$done=!empty($e['is_completed']);$unlocked=!empty($e['is_unlocked']); ?><a class="chapter <?= $unlocked?'':'locked'; ?>" href="<?= base_url('belajar/english-quest/'.$e['code']); ?>"><?php if(!$unlocked): ?><span class="lock"><i class="ti ti-lock"></i></span><?php endif; ?><span class="icon"><?= $icons[$i%count($icons)]; ?></span><div class="tag">CHAPTER <?= $i+1; ?> · <?= $done?'SELESAI':($unlocked?'TERBUKA':'TERKUNCI'); ?></div><h2><?= html_escape($e['title']); ?></h2><p class="text-secondary"><?= html_escape($e['description']); ?></p><div class="d-flex justify-content-between"><small><?= $current; ?>/<?= $total; ?> adegan</small><b><?= (int)($e['xp']??0); ?> XP</b></div><div class="bar"><i style="width:<?= $done?100:min(100,$current/$total*100); ?>%"></i></div></a><?php endforeach; ?></section></main></body></html>
